var n=`1299-feijao-tropeiro`;var t=`world-1299`;var a=`BR`;var o=`south-america`;var s=4;var r=531;var u={en:`Feijão Tropeiro`,ua:`Фейжау тропейру`};var d={en:`Feijão Tropeiro is a dish from Brazil featuring pinto beans, bacon, fresh pork sausage, yellow onion. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Фейжау тропейру, страва кухні країни Бразилія з такими основними складниками: квасоля пінто, бекон, сира свиняча ковбаса, жовта цибуля. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var g=[{en:`Soak the dried beans in ample clean cold water for about 410 minutes, drain and discard the soaking water; cook fully in fresh water.`,ua:`Замочіть сухі бобові у достатній кількості чистої холодної води на приблизно 410 хвилин, злийте її й повністю зваріть у свіжій воді.`,t:[`soaking-legumes`],m:410,i:[[`pinto-beans`,360,`g`],[`water`,950,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 90 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 90 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:90,i:[[`water`,1100,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 10 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 10 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:10,i:[[`bacon`,160,`g`],[`fresh-pork-sausage`,220,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,180,`g`],[`garlic`,4,`clove`],[`collard-greens`,220,`g`]]},{en:`Toast these ingredients over medium heat for about 9 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 9 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:9,i:[[`cassava-flour`,180,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`chicken-egg`,3,`pcs`]]}];var l={slug:n,id:t,country:`BR`,region:o,servings:4,minutes:531,title:u,text:d,steps:g};export{a as country,l as default,t as id,r as minutes,o as region,s as servings,n as slug,g as steps,d as text,u as title};